  "routes[route-bl-urahara-path].steps[1].description": "Condamné pour la Hollowification orchestrée par Aizen, il s’enfuit avec Tessai et les Visards.",
  "routes[route-bl-urahara-path].steps[2].label": "Boutique Urahara",
  "routes[route-bl-urahara-path].steps[2].description": "Sa couverture à Karakura : c’est d’ici qu’il veille sur Ichigo et ses amis.",
  "routes[route-bl-urahara-path].steps[3].label": "Salle d’entraînement",
  "routes[route-bl-urahara-path].steps[3].description": "Le Shattered Shaft rend ses pouvoirs à Ichigo.",
