  "routes[route-bl-urahara-path].steps[5].description": "Avec Yoruichi et Grimmjow contre Askin Nakk Le Vaar.",
  "routes[route-bl-byakuya-path].localizedName": "Le chemin de Byakuya",
  "routes[route-bl-byakuya-path].description": "Le chef du clan Kuchiki, déchiré entre la loi et la promesse faite à son épouse Hisana : de l’adoption de Rukia à sa défaite face à Ichigo, jusqu’à son retour du Reiôkyû.",
  "routes[route-bl-byakuya-path].steps[0].label": "Manoir Kuchiki",
  "routes[route-bl-byakuya-path].steps[0].description": "Il adopte Rukia, la sœur de feu Hisana.",
  "routes[route-bl-byakuya-path].steps[1].label": "Karakura",
  "routes[route-bl-byakuya-path].steps[1].description": "Avec Renji, il arrête Rukia et terrasse Ichigo.",
  "routes[route-bl-byakuya-path].steps[2].label": "Senzaikyû",
  "routes[route-bl-byakuya-path].steps[2].description": "Il bat Renji, qui tente de sauver Rukia.",
  "routes[route-bl-byakuya-path].steps[3].label": "Colline du Sôkyoku",
  "routes[route-bl-byakuya-path].steps[3].description": "Sa défaite face à Ichigo change sa vision de la loi.",
  "routes[route-bl-byakuya-path].steps[4].label": "Las Noches",
  "routes[route-bl-byakuya-path].steps[4].description": "Il protège Rukia et abat Zommari Rureaux.",
  "routes[route-bl-byakuya-path].steps[5].label": "6e division",
  "routes[route-bl-byakuya-path].steps[5].description": "Son Bankai volé et sa défaite face à Äs Nödt.",
  "routes[route-bl-byakuya-path].steps[6].label": "Kirinden",
  "routes[route-bl-byakuya-path].steps[6].description": "Soigné au Reiôkyû pour pouvoir se battre à nouveau.",
  "routes[route-bl-ulquiorra-path].localizedName": "Le chemin d'Ulquiorra",
  "routes[route-bl-ulquiorra-path].description": "Le Cuarto Espada qui ne croit pas au cœur : de sa première reconnaissance à Karakura à l’enlèvement d’Orihime, jusqu’au dernier combat au sommet du dôme de Las Noches.",
  "routes[route-bl-ulquiorra-path].steps[0].label": "Karakura",
  "routes[route-bl-ulquiorra-path].steps[0].description": "Avec Yammy, il jauge Ichigo pour le compte d’Aizen.",
